-- Seed de usuarios de prueba para PostgreSQL
-- Ejecutar después de sql/db_MuniQuejas.sql.
-- Los hashes de contraseña son los existentes en la base local (BCrypt).
-- Este script es idempotente: puede ejecutarse más de una vez sin duplicar filas.

BEGIN;

-- Roles base con IDs explícitos para que coincidan con las credenciales del seed
ON CONFLICT (rol_user_id) DO NOTHING;

-- Credenciales de prueba
-- Nota: user_id=3 existe en la base local pero no tiene fila en usuarios; se conserva igual.

-- Usuarios de prueba

-- Ajustar secuencias después de insertar IDs explícitos
SELECT setval('public.rol_user_rol_user_id_seq',
              (SELECT MAX(rol_user_id) FROM public.rol_user));
SELECT setval('public.credenciales_user_id_seq',
              (SELECT MAX(user_id) FROM public.credenciales));
SELECT setval('public.usuarios_usuario_id_seq',
              (SELECT MAX(usuario_id) FROM public.usuarios));

COMMIT;
